def _print_results(rag: MetadataRAG, query: str, filt: Optional[Dict[str, Any]], k: int, use_mmr: bool) -> None:
    print("=" * 74)
    print(f"QUERY : {query}")
    if filt:
        print(f"FILTER: {json.dumps(filt, ensure_ascii=False)}")
    results = rag.search(query, filter_spec=filt, k=k, use_mmr=use_mmr)
    print("\nRanked retrieval (metadata-filtered, hybrid relevance):")
    if not results:
        print("  (no chunks matched the filter)")
    for r in results:
        src = r.chunk.metadata.get("source", "?")
        preview = r.chunk.text.replace("\n", " ")[:90]
        print(
            f"  #{r.rank} fused={r.score:.3f} dense={r.dense_score:.3f} "
            f"sparse={r.sparse_score:.3f} | {src} | {preview!r}"
        )
    answer = rag.answer(query, filter_spec=filt, k=k, use_mmr=use_mmr)
    print("\nANSWER:", answer["answer"])
    print("CONFIDENCE:", answer["confidence"])
    print("SOURCES  :", [s["source"] for s in answer["sources"]])
    print()


def run_demo(args: argparse.Namespace) -> None:
    rag = MetadataRAG(embedder=make_embedder(args.embedder), chunk_size=600, chunk_overlap=80)
    if args.llm == "openai":
        rag.llm = openai_chat_llm()
    docs = build_demo_documents()
    indexed = rag.add_documents(docs)
    print(f"Indexed {indexed} chunks from {len(docs)} documents "
          f"(embedder={rag.embedder.name}, dense+BM25 hybrid, metadata filters).\n")

    if args.query:
        queries: List[Tuple[str, Optional[Dict[str, Any]]]] = [
            (args.query, parse_metadata_filter(args.filter))
        ]
    else:
        queries = [
            ("How do I set up role-based access control for my team?",
             {"category": "guides", "status": "active"}),
            ("Which REST API endpoints are available?",
             {"tags": {"$contains": "api"}, "status": "active"}),
            ("How should I troubleshoot connection timeouts?",
             {"priority": {"$gte": 3}}),
            ("What are the options for self-hosted or on-premise deployment?",
             {"$or": [{"category": "guides"}, {"category": "engineering"}]}),
            ("How do data retention policies work for compliance?",
             {"date": {"$gte": "2025-01-01"}, "category": "guides"}),
            ("What changed in version 2.1.0?",
             {"version": {"$startsWith": "2.1"}, "category": "changelog"}),
        ]
    for query, filt in queries:
        _print_results(rag, query, filt, k=args.k, use_mmr=args.mmr)

    # Quick retrieval-quality evaluation using chunk indices.
    print("-" * 74)
    print("Retrieval evaluation (hit rate / MRR / precision@k):")
    idx_by_doc = {}
    for i, chunk in enumerate(rag.store.chunks):
        base = chunk.chunk_id.split("::")[0]
        idx_by_doc.setdefault(base, []).append(i)
    labelled = {
        "How do I set up role-based access control for my team?": idx_by_doc.get("rbac", []),
        "Which REST API endpoints are available?": idx_by_doc.get("rest-api", []),
        "How should I troubleshoot connection timeouts?": idx_by_doc.get("timeouts", []),
    }
    metrics = evaluate_retrieval(rag, list(labelled.keys()), labelled, k=args.k)
    print(" ", json.dumps(metrics, indent=2))


def run_build(args: argparse.Namespace) -> None:
    rag = MetadataRAG(embedder=make_embedder(args.embedder), chunk_size=600, chunk_overlap=80)
    docs = build_demo_documents()
    indexed = rag.add_documents(docs)
    rag.save(args.out)
    print(f"Built index with {indexed} chunks from {len(docs)} documents -> {args.out}")


def run_search(args: argparse.Namespace) -> None:
    rag = MetadataRAG.load(args.index, embedder=make_embedder(args.embedder) if args.embedder else None)
    filt = parse_metadata_filter(args.filter)
    _print_results(rag, args.query, filt, k=args.k, use_mmr=args.mmr)


def main(argv: Optional[Sequence[str]] = None) -> None:
    parser = argparse.ArgumentParser(
        prog="rag_metadata_system",
        description="RAG with metadata filtering and relevance ranking.",
    )
    sub = parser.add_subparsers(dest="command")

    demo = sub.add_parser("demo", help="Run the built-in demo corpus and queries")
    demo.add_argument("--query", default=None, help="Custom query (default: demo queries)")
    demo.add_argument("--filter", default=None, help='JSON metadata filter, e.g. \'{"category": "guides"}\'')
    demo.add_argument("--k", type=int, default=4, help="Number of chunks to retrieve")
    demo.add_argument("--mmr", action="store_true", help="Diversify results with MMR")
    demo.add_argument("--embedder", default="hash", help="hash | st | openai")
    demo.add_argument("--llm", default=None, choices=[None, "openai"], help="Optional generative LLM backend")
    demo.set_defaults(func=run_demo)

    build = sub.add_parser("build", help="Build a persistent index from the demo corpus")
    build.add_argument("--out", default="rag_index.json", help="Output index file")
    build.add_argument("--embedder", default="hash", help="hash | st | openai")
    build.set_defaults(func=run_build)

    search = sub.add_parser("search", help="Search a persisted index")
    search.add_argument("--index", default="rag_index.json", help="Index file to load")
    search.add_argument("--query", required=True, help="Query text")
    search.add_argument("--filter", default=None, help='JSON metadata filter')
    search.add_argument("--k", type=int, default=4, help="Number of chunks to retrieve")
    search.add_argument("--mmr", action="store_true", help="Diversify results with MMR")
    search.add_argument("--embedder", default=None, help="Override embedder kind (hash | st | openai)")
    search.set_defaults(func=run_search)

    args = parser.parse_args(argv)
    if getattr(args, "func", None):
        args.func(args)
    else:
        parser.print_help()


if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""
RAG-Meta: Retrieval-Augmented Generation with Metadata Filtering
and Relevance Ranking
================================================================

A self-contained RAG system that:

1. Ingests documents, splits them into chunks, and indexes dense
   embeddings plus a sparse (BM25) keyword index.
2. Filters candidate chunks by structured metadata *before* ranking,
   using an expressive filter language (equality, comparison, membership,
   substring/contains, regex, existence, and ``$and``/``$or``/``$not``).
3. Ranks the surviving chunks by hybrid relevance (dense semantic
   similarity + sparse BM25), with optional cross-encoder reranking and
   Maximal Marginal Relevance (MMR) diversification.
4. Answers user queries grounded in the top-ranked chunks, emitting
   citations back to the source metadata, with an extractive fallback
   when no LLM is configured.

Design notes
------------
* Zero-dependency mode: the built-in ``HashEmbedder`` produces
  deterministic L2-normalized hashing-trick embeddings, so the system
  runs anywhere with plain Python.
* Optional embedders: ``sentence-transformers`` (local models) or
  ``openai`` (API key) via ``--embedder st|openai``.
* Optional generative LLM: ``--llm openai`` wires the OpenAI chat
  completions API into the QA prompt; otherwise an extractive answerer
  returns the most relevant sentences and a confidence score.

CLI
---
    python rag_metadata_system.py demo
    python rag_metadata_system.py build --out rag_index.json
    python rag_metadata_system.py search --index rag_index.json \
        --query "How do I set up RBAC?" \
        --filter '{"category": "guides", "status": "active"}'
"""

