# --------------------------------------------------------------------------
# Text utilities
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[A-Za-z0-9_]+|[\u4e00-\u9fff]")


def tokenize(text: Optional[str]) -> List[str]:
    """Deterministic, dependency-free tokenization used by BM25 and scores."""
    if not text:
        return []
    return [t.lower() for t in _TOKEN_RE.findall(text)]


def cosine_similarity(a: Optional[Sequence[float]], b: Optional[Sequence[float]]) -> float:
    if not a or not b or len(a) != len(b):
        return 0.0
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    if na == 0.0 or nb == 0.0:
        return 0.0
    return dot / (na * nb)


def minmax_normalize(values: Sequence[float]) -> List[float]:
    """Scale a list of scores into [0, 1]. Degenerate input maps to 1.0."""
    if not values:
        return []
    lo, hi = min(values), max(values)
    if hi - lo < 1e-12:
        return [1.0] * len(values)
    return [(v - lo) / (hi - lo) for v in values]


# --------------------------------------------------------------------------
# Data structures
# --------------------------------------------------------------------------


@dataclass
class Chunk:
    """A retrievable unit of text with its metadata and (optional) embedding."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    chunk_id: str = ""
    token_count: int = 0
    embedding: Optional[List[float]] = None


@dataclass
class Document:
    """A source document before splitting."""

    page_content: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: str = ""


@dataclass
class RankedResult:
    """One retrieval hit with its fused relevance scores."""

    rank: int
    chunk: Chunk
    score: float          # fused hybrid score
    dense_score: float    # normalized dense similarity component
    sparse_score: float   # normalized sparse (BM25) component
    rerank_score: Optional[float] = None


@dataclass
class RankingWeights:
    """Relative weight of dense vs sparse relevance in hybrid ranking."""

    dense: float = 0.7
    sparse: float = 0.3

    def __post_init__(self) -> None:
        total = self.dense + self.sparse
        if total <= 0.0:
            raise ValueError("Ranking weights must sum to a positive value")
        self.dense = self.dense / total
        self.sparse = self.sparse / total


# --------------------------------------------------------------------------
# Text splitting
# --------------------------------------------------------------------------


class RecursiveTextSplitter:
    """Split documents into overlapping chunks using a separator hierarchy.

    Larger sections (paragraphs) are preferred; chunks are guaranteed not
    to exceed ``chunk_size`` characters and keep ``chunk_overlap`` of
    trailing context to preserve information across boundaries.
    """

    def __init__(
        self,
        chunk_size: int = 800,
        chunk_overlap: int = 100,
        separators: Optional[List[str]] = None,
    ) -> None:
        if chunk_overlap >= chunk_size:
            raise ValueError("chunk_overlap must be smaller than chunk_size")
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap
        self.separators = separators or ["\n\n", "\n", ". ", " ", ""]

    # -- internals --------------------------------------------------------

    def _split_recursive(self, text: str, seps: Sequence[str]) -> List[str]:
        """Split ``text`` into segments, each at most ``chunk_size`` long."""
        if len(text) <= self.chunk_size:
            return [text]
        if not seps:
            return [text]
        sep = seps[0]
        if not sep:
            return [text[i:i + self.chunk_size] for i in range(0, len(text), self.chunk_size)]
        if sep in text:
            parts = text.split(sep)
            out: List[str] = []
            buf = ""
            for part in parts:
                cand = (buf + sep + part) if buf else part
                if len(cand) <= self.chunk_size:
                    buf = cand
                else:
                    if buf:
                        out.append(buf)
                    out.extend(self._split_recursive(part, seps[1:]))
                    buf = ""
            if buf:
                out.append(buf)
            return out
        return self._split_recursive(text, seps[1:])

    # -- public API -------------------------------------------------------

    def split_text(self, text: str) -> List[str]:
        normalized = (text or "").replace("\r\n", "\n")
        chunks: List[str] = []
        for segment in self._split_recursive(normalized, self.separators):
            length = len(segment)
            if length <= self.chunk_size:
                chunks.append(segment)
                continue
            start = 0
            while start < length:
                end = start + self.chunk_size
                chunks.append(segment[start:end])
                if end >= length:
                    break
                start = end - self.chunk_overlap
        return [c for c in chunks if c and c.strip()]

    def split_documents(self, documents: Iterable[Document]) -> List[Chunk]:
        chunks: List[Chunk] = []
        for i, doc in enumerate(documents):
            base_id = doc.doc_id or f"doc-{i}"
            for j, text in enumerate(self.split_text(doc.page_content)):
                chunks.append(
                    Chunk(
                        text=text,
                        metadata=dict(doc.metadata),
                        chunk_id=f"{base_id}::chunk{j}",
                        token_count=len(tokenize(text)),
                    )
                )
        return chunks


# --------------------------------------------------------------------------
# Embedders
# --------------------------------------------------------------------------


class BaseEmbedder:
    """Embedding backend interface. Subclasses set ``name`` and implement ``embed``."""

    name = "base"

    def embed(self, text: str) -> List[float]:
        raise NotImplementedError

    def embed_many(self, texts: Sequence[str]) -> List[List[float]]:
        return [self.embed(t) for t in texts]


class HashEmbedder(BaseEmbedder):
    """Dependency-free hashing-trick embeddings.

    Uses signed MD5 hashes over word and word-pair features so that
    semantically overlapping text shares vector support, then L2-normalizes.
    Good enough for demos, tests, and offline pipelines.
    """

    name = "hash"

    def __init__(self, dim: int = 256, ngram: Tuple[int, int] = (1, 2)) -> None:
        self.dim = dim
        self.ngram = ngram

    def embed(self, text: str) -> List[float]:
        vec = [0.0] * self.dim
        tokens = tokenize(text)
        if not tokens:
            return vec
        for n in range(self.ngram[0], self.ngram[1] + 1):
            if n > len(tokens):
                continue
            for i in range(len(tokens) - n + 1):
                gram = " ".join(tokens[i:i + n])
                digest = hashlib.md5(gram.encode("utf-8")).digest()
                idx = int.from_bytes(digest[:4], "big") % self.dim
                sign = 1.0 if digest[4] % 2 == 0 else -1.0
                vec[idx] += sign
        norm = math.sqrt(sum(v * v for v in vec)) or 1.0
        return [v / norm for v in vec]


class SentenceTransformersEmbedder(BaseEmbedder):
    """Local embedding model via the ``sentence-transformers`` package."""

    name = "sentence-transformers"

    def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError as exc:  # pragma: no cover - environment guard
            raise ImportError(
                "SentenceTransformersEmbedder requires `pip install sentence-transformers`"
            ) from exc
        self.model_name = model_name
        self.model = SentenceTransformer(model_name)

    def embed(self, text: str) -> List[float]:
        vector = self.model.encode([text], normalize_embeddings=True)[0]
        return [float(v) for v in vector]

    def embed_many(self, texts: Sequence[str]) -> List[List[float]]:
        vectors = self.model.encode(list(texts), normalize_embeddings=True)
        return [[float(v) for v in row] for row in vectors]


class OpenAIEmbedder(BaseEmbedder):
    """OpenAI embeddings API backend (requires ``openai`` + key)."""

    name = "openai"

    def __init__(self, model: str = "text-embedding-ada-002", api_key: Optional[str] = None) -> None:
        try:
            import openai  # noqa: F401
        except ImportError as exc:  # pragma: no cover
            raise ImportError("OpenAIEmbedder requires `pip install openai`") from exc
        self.model = model
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OpenAI API key required; pass api_key= or set OPENAI_API_KEY")

    def embed(self, text: str) -> List[float]:
        import openai

        client = openai.OpenAI(api_key=self.api_key)
        response = client.embeddings.create(input=[text], model=self.model)
        return [float(v) for v in response.data[0].embedding]

    def embed_many(self, texts: Sequence[str]) -> List[List[float]]:
        import openai

        client = openai.OpenAI(api_key=self.api_key)
        response = client.embeddings.create(input=list(texts), model=self.model)
        ordered = sorted(response.data, key=lambda d: d.index)
        return [[float(v) for v in item.embedding] for item in ordered]


def make_embedder(kind: Optional[str] = None, model: Optional[str] = None) -> BaseEmbedder:
    """Factory: ``hash`` (default), ``st``/``sentence-transformers``, or ``openai``."""
    kind = (kind or "hash").lower()
    if kind in ("hash", "hashing"):
        return HashEmbedder()
    if kind in ("st", "sbert", "sentence-transformers", "sentence_transformers"):
        return SentenceTransformersEmbedder(model or "all-MiniLM-L6-v2")
    if kind in ("openai", "ada", "text-embedding"):
        return OpenAIEmbedder(model or "text-embedding-ada-002")
    raise ValueError(f"Unknown embedder kind: {kind!r}")


# --------------------------------------------------------------------------
# Sparse retrieval: BM25
# --------------------------------------------------------------------------


class BM25Index:
    """Okapi BM25 over the chunks currently in the store."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self._doc_tokens: List[List[str]] = []
        self._doc_len: List[int] = []
        self._df: Counter = Counter()
        self._idf: Dict[str, float] = {}
        self._avgdl = 0.0

    def fit(self, tokenized_docs: Iterable[List[str]]) -> None:
        self._doc_tokens = [list(t) for t in tokenized_docs]
        self._doc_len = [len(t) for t in self._doc_tokens]
        n = len(self._doc_tokens)
        self._avgdl = (sum(self._doc_len) / n) if n else 0.0
        self._df = Counter()
        for tokens in self._doc_tokens:
            for tok in set(tokens):
                self._df[tok] += 1
        self._idf = {
            tok: math.log(1.0 + (n - df + 0.5) / (df + 0.5))
            for tok, df in self._df.items()
        }

    def score(self, query_tokens: Sequence[str], doc_idx: int) -> float:
        if not query_tokens or doc_idx < 0 or doc_idx >= len(self._doc_tokens):
            return 0.0
        tokens = self._doc_tokens[doc_idx]
        dl = self._doc_len[doc_idx] or 1
        tf_counter = Counter(tokens)
        total = 0.0
        for qt in set(query_tokens):
            tf = tf_counter.get(qt, 0)
            if tf == 0:
                continue
            idf = self._idf.get(qt, 0.0)
            denom = tf + self.k1 * (1.0 - self.b + self.b * dl / max(self._avgdl, 1e-9))
            total += idf * (tf * (self.k1 + 1.0)) / denom
        return total

    def scores(self, query_tokens: Sequence[str]) -> List[float]:
        return [self.score(query_tokens, i) for i in range(len(self._doc_tokens))]


# --------------------------------------------------------------------------
# Metadata filtering
# --------------------------------------------------------------------------

_META_OPS = (
    "$eq", "$ne", "$in", "$nin", "$gt", "$gte", "$lt", "$lte",
    "$contains", "$startsWith", "$endsWith", "$regex", "$exists",
)


def _lookup(metadata: Mapping[str, Any], key: str) -> Any:
    """Read ``a.b.c`` dotted paths (and list indices) from metadata."""
    node: Any = metadata
    for part in key.split("."):
        if isinstance(node, dict):
            node = node.get(part)
        elif isinstance(node, list):
            try:
                node = node[int(part)]
            except (ValueError, IndexError, TypeError):
                return None
        else:
            return None
        if node is None:
            return None
    return node


def _matches_operator(value: Any, op: str, expected: Any) -> bool:
    if op == "$eq":
        return value == expected
    if op == "$ne":
        return value != expected
    if op == "$in":
        return isinstance(expected, (list, tuple, set)) and value in expected
    if op == "$nin":
        return isinstance(expected, (list, tuple, set)) and value not in expected
    if op in ("$gt", "$gte", "$lt", "$lte"):
        try:
            if op == "$gt":
                return bool(value > expected)
            if op == "$gte":
                return bool(value >= expected)
            if op == "$lt":
                return bool(value < expected)
            return bool(value <= expected)
        except TypeError:
            return False
    if op == "$contains":
        if isinstance(value, str) and isinstance(expected, str):
            return expected in value
        if isinstance(value, (list, tuple, set)):
            return expected in value
        return False
    if op == "$startsWith":
        return isinstance(value, str) and isinstance(expected, str) and value.startswith(expected)
    if op == "$endsWith":
        return isinstance(value, str) and isinstance(expected, str) and value.endswith(expected)
    if op == "$regex":
        try:
            return isinstance(value, str) and re.search(expected, value) is not None
        except re.error:
            return False
    if op == "$exists":
        present = value is not None
        return present if bool(expected) else not present
    return False


def evaluate_filter(metadata: Mapping[str, Any], spec: Optional[Mapping[str, Any]]) -> bool:
    """Evaluate a metadata filter spec against one chunk's metadata.

    Supported forms::

        {"category": "guides"}                       # equality
        {"tags": {"$contains": "api"}}               # operator on a key
        {"priority": {"$gte": 3}}                    # comparisons
        {"date": {"$gte": "2025-01-01", "$lt": "2026-01-01"}}
        {"$and": [spec1, spec2]}                     # all must match
        {"$or": [spec1, spec2]}                      # at least one
        {"$not": spec}                               # negation
        {"author.name": "Maria"}                     # dotted paths

    An empty/``None`` spec matches everything (no filtering).
    """
    if not spec:
        return True
    if not isinstance(spec, dict):
        return True

    if "$and" in spec:
        subs = spec["$and"]
        return isinstance(subs, list) and all(
            evaluate_filter(metadata, s) for s in subs
        )
    if "$or" in spec:
        subs = spec["$or"]
        return isinstance(subs, list) and any(
            evaluate_filter(metadata, s) for s in subs
        )
    if "$not" in spec:
        return not evaluate_filter(metadata, spec["$not"])

    for key, condition in spec.items():
        if str(key).startswith("$"):
            continue
        value = _lookup(metadata, str(key))
        if isinstance(condition, dict):
            has_operator = any(str(op).startswith("$") for op in condition)
            if not has_operator:
                # Nested metadata object compared for equality.
                if value != condition:
                    return False
                continue
            for op, expected in condition.items():
                if str(op).startswith("$") and not _matches_operator(value, str(op), expected):
                    return False
        elif value != condition:
            return False
    return True


def parse_metadata_filter(text: Optional[str]) -> Optional[Dict[str, Any]]:
    """Parse a JSON filter string from the CLI (``None``/empty -> no filter)."""
    if text is None or not text.strip():
        return None
    loaded = json.loads(text)
    if not isinstance(loaded, dict):
        raise ValueError("Metadata filter must be a JSON object")
    return loaded


# --------------------------------------------------------------------------
# Vector store
# --------------------------------------------------------------------------


class MetadataVectorStore:
    """In-memory store of chunks with dense embeddings, BM25, and filters."""

    def __init__(self, embedder: BaseEmbedder) -> None:
        self.embedder = embedder
        self.chunks: List[Chunk] = []
        self._bm25 = BM25Index()
        self._bm25_fresh = False
        self._bm25_tokens: List[List[str]] = []

    # -- indexing ---------------------------------------------------------

    def add_chunks(self, chunks: Iterable[Chunk]) -> int:
        added = 0
        for chunk in chunks:
            if not chunk.text or not chunk.text.strip():
                continue
            if chunk.embedding is None:
                chunk.embedding = self.embedder.embed(chunk.text)
            if not chunk.chunk_id:
                chunk.chunk_id = f"chunk-{len(self.chunks)}"
            self.chunks.append(chunk)
            added += 1
        self._bm25_fresh = False
        return added

    def _ensure_bm25(self) -> None:
        if self._bm25_fresh:
            return
        self._bm25_tokens = [tokenize(c.text) for c in self.chunks]
        self._bm25.fit(self._bm25_tokens)
        self._bm25_fresh = True

    # -- filtering --------------------------------------------------------

    def filtered_indices(self, filter_spec: Optional[Mapping[str, Any]] = None) -> List[int]:
        """Chunk indices that satisfy the metadata filter (all if None)."""
        if not filter_spec:
            return list(range(len(self.chunks)))
        return [
            i for i, c in enumerate(self.chunks)
            if evaluate_filter(c.metadata, filter_spec)
        ]


# --------------------------------------------------------------------------
# Ranking helpers
# --------------------------------------------------------------------------


def _score_candidates(
    store: MetadataVectorStore,
    query_tokens: Sequence[str],
    query_embedding: Sequence[float],
    indices: Sequence[int],
    weights: RankingWeights,
) -> List[Tuple[int, float, float, float]]:
    """Return ``(chunk_index, norm_dense, norm_sparse, fused)`` per candidate."""
    dense: List[float] = []
    for i in indices:
        emb = store.chunks[i].embedding
        dense.append(cosine_similarity(query_embedding, emb) if emb else 0.0)
    store._ensure_bm25()
    sparse_all = store._bm25.scores(query_tokens)
    dense_n = minmax_normalize(dense)
    sparse_n = minmax_normalize([sparse_all[i] for i in indices])
    out: List[Tuple[int, float, float, float]] = []
    for (i, _d), dn, sn in zip(zip(indices, dense), dense_n, sparse_n):
        fused = weights.dense * dn + weights.sparse * sn
        out.append((i, dn, sn, fused))
    return out


def maximal_marginal_relevance(
    query_embedding: Optional[Sequence[float]],
    candidates: Sequence[Tuple[int, float]],
    store: MetadataVectorStore,
    lambda_mult: float = 0.7,
) -> List[int]:
    """Greedy MMR selection: relevance to query minus redundancy vs chosen.

    ``candidates`` is ``(chunk_index, relevance_score)``. Returns all
    selected indices in selection order; callers slice to ``k``.
    """
    if not candidates:
        return []
    remaining = list(candidates)
    embeddings: Dict[int, Optional[List[float]]] = {
        i: store.chunks[i].embedding for i, _ in candidates
    }
    q = list(query_embedding) if query_embedding else None
    selected: List[int] = []
    while remaining:
        best_pos = 0
        best_mmr = -math.inf
        for pos, (i, _rel) in enumerate(remaining):
            emb = embeddings.get(i)
            if not emb:
                continue
            sim_q = cosine_similarity(q, emb) if q else 0.0
            sim_sel = 0.0
            if selected:
                sim_sel = max(
                    (cosine_similarity(emb, embeddings[j]) for j in selected if embeddings.get(j)),
                    default=0.0,
                )
            mmr = lambda_mult * sim_q - (1.0 - lambda_mult) * sim_sel
            if mmr > best_mmr:
                best_mmr = mmr
                best_pos = pos
        selected.append(remaining.pop(best_pos)[0])
    return selected


class CrossEncoderReranker:
    """Optional reranker using a sentence-transformers cross-encoder."""

    def __init__(self, model_name: str = "cross-encoder/ms-marco-MiniLM-L-6-v2") -> None:
        try:
            from sentence_transformers import CrossEncoder
        except ImportError as exc:  # pragma: no cover
            raise ImportError(
                "CrossEncoderReranker requires `pip install sentence-transformers`"
            ) from exc
        self.model_name = model_name
        self.model = CrossEncoder(model_name)

    def rerank(self, query: str, chunks: Sequence[Chunk]) -> List[float]:
        pairs = [[query, c.text] for c in chunks]
        scores = self.model.predict(pairs)
        return [float(s) for s in scores]


# --------------------------------------------------------------------------
# Generation: prompts, extractive fallback, optional LLM
# --------------------------------------------------------------------------

QA_PROMPT_TEMPLATE = """Use the following context to answer the question. If the context does not contain enough information to answer, say "I don't have enough information to answer this question." Cite the context passages you used by their tags, e.g. [1], [2].

Context:
{context}

Question: {question}

Answer:"""


def extractive_answer(query: str, results: Sequence[RankedResult]) -> Tuple[str, float]:
    """Grounded extractive fallback: answer from the top-ranked chunk's sentences."""
    if not results:
        return "I don't have enough information to answer this question.", 0.0
    best = results[0].chunk
    q_tokens = set(tokenize(query))
    sentences = re.split(r"(?<=[.!?])\s+|\n+", best.text)
    picked: List[str] = []
    for sent in sentences:
        if q_tokens & set(tokenize(sent)):
            picked.append(sent)
        if len(" ".join(picked)) > 400:
            break
    if not picked:
        picked = [best.text.strip()[:400]]
    answer = " ".join(picked).strip()
    overlap = len(q_tokens & set(tokenize(best.text))) / max(len(q_tokens), 1)
    confidence = round(0.4 + 0.6 * min(1.0, results[0].score * overlap * 2.0), 2)
    return answer, confidence


def openai_chat_llm(
    model: str = "gpt-4o-mini",
    api_key: Optional[str] = None,
    temperature: float = 0.1,
) -> Callable[[str, str], str]:
    """Build a ``(query, context) -> answer`` LLM callable on the OpenAI API."""
    try:
        import openai
    except ImportError as exc:  # pragma: no cover
        raise ImportError("openai_chat_llm requires `pip install openai`") from exc
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError("OpenAI API key required; pass api_key= or set OPENAI_API_KEY")
    client = openai.OpenAI(api_key=key)

    def _llm(query: str, context: str) -> str:
        prompt = QA_PROMPT_TEMPLATE.format(context=context, question=query)
        response = client.chat.completions.create(
            model=model,
            temperature=temperature,
            messages=[{"role": "user", "content": prompt}],
        )
        return response.choices[0].message.content.strip()

    return _llm


# --------------------------------------------------------------------------
# High-level RAG system
# --------------------------------------------------------------------------


class MetadataRAG:
    """Retrieval-Augmented Generation with metadata filtering and ranking.

    Usage::

        rag = MetadataRAG(embedder=make_embedder("hash"))
        rag.add_documents([Document(page_content="...", metadata={...})])
        results = rag.search(
            "how do I configure RBAC?",
            filter_spec={"category": "guides", "status": "active"},
            k=4,
        )
        answer = rag.answer("how do I configure RBAC?", filter_spec=...)
    """

    def __init__(
        self,
        embedder: Optional[BaseEmbedder] = None,
        chunk_size: int = 800,
        chunk_overlap: int = 100,
        weights: Optional[RankingWeights] = None,
        llm: Optional[Callable[[str, str], str]] = None,
    ) -> None:
        self.embedder = embedder or make_embedder("hash")
        self.store = MetadataVectorStore(self.embedder)
        self.splitter = RecursiveTextSplitter(chunk_size=chunk_size, chunk_overlap=chunk_overlap)
        self.weights = weights or RankingWeights()
        self.llm = llm

    # -- indexing ---------------------------------------------------------

    def add_documents(self, documents: Iterable[Document]) -> int:
        docs = list(documents)
        chunks = self.splitter.split_documents(docs)
        return self.store.add_chunks(chunks)

    def add_chunks(self, chunks: Iterable[Chunk]) -> int:
        return self.store.add_chunks(list(chunks))

    # -- retrieval --------------------------------------------------------

    def search(
        self,
        query: str,
        filter_spec: Optional[Mapping[str, Any]] = None,
        k: int = 4,
        use_mmr: bool = False,
        lambda_mult: float = 0.7,
        reranker: Optional[CrossEncoderReranker] = None,
    ) -> List[RankedResult]:
        """Retrieve chunks filtered by metadata, ranked by hybrid relevance.

        Pipeline:
        1. ``store.filtered_indices`` prunes candidates using metadata.
        2. Hybrid scoring: normalized dense cosine + normalized BM25.
        3. Optional cross-encoder reranking over the top ``4*k``.
        4. Optional MMR diversification.
        """
        if not query or not query.strip():
            return []
        query_tokens = tokenize(query)
        query_embedding = self.embedder.embed(query)
        indices = self.store.filtered_indices(filter_spec)
        if not indices:
            return []

        scored = _score_candidates(self.store, query_tokens, query_embedding, indices, self.weights)
        scored.sort(key=lambda e: e[3], reverse=True)

        if reranker is not None and scored:
            fetch_n = min(max(k * 4, 20), len(scored))
            fetch = scored[:fetch_n]
            cand_chunks = [self.store.chunks[i] for i, _, _, _ in fetch]
            rerank_scores = reranker.rerank(query, cand_chunks)
            reordered = sorted(zip(fetch, rerank_scores), key=lambda p: p[1], reverse=True)
            scored = [entry for entry, _ in reordered[:k]]
            rerank_map = {id(entry[0]): rs for entry, rs in reordered}

        by_index = {i: (dn, sn, fused) for i, dn, sn, fused in scored}

        if use_mmr and scored:
            ordered = maximal_marginal_relevance(
                query_embedding,
                [(i, fused) for i, _, _, fused in scored],
                self.store,
                lambda_mult=lambda_mult,
            )[:k]
        else:
            ordered = [i for i, _, _, _ in scored[:k]]

        results: List[RankedResult] = []
        for pos, i in enumerate(ordered, start=1):
            dn, sn, fused = by_index[i]
            results.append(
                RankedResult(
                    rank=pos,
                    chunk=self.store.chunks[i],
                    score=fused,
                    dense_score=dn,
                    sparse_score=sn,
                    rerank_score=rerank_map.get(id(i)) if reranker is not None else None,
                )
            )
        return results

    # -- generation -------------------------------------------------------

    def answer(
        self,
        query: str,
        filter_spec: Optional[Mapping[str, Any]] = None,
        k: int = 4,
        use_mmr: bool = False,
        lambda_mult: float = 0.7,
        reranker: Optional[CrossEncoderReranker] = None,
        llm: Optional[Callable[[str, str], str]] = None,
    ) -> Dict[str, Any]:
        """End-to-end grounded answer with citations.

        Returns a dict with ``query``, ``answer``, ``confidence``,
        ``sources`` (each with rank, source, text, metadata, score), and the
        assembled ``context``.
        """
        results = self.search(
            query,
            filter_spec=filter_spec,
            k=k,
            use_mmr=use_mmr,
            lambda_mult=lambda_mult,
            reranker=reranker,
        )
        context_parts: List[str] = []
        sources: List[Dict[str, Any]] = []
        for r in results:
            src = r.chunk.metadata.get("source", r.chunk.chunk_id or "unknown")
            context_parts.append(f"[{r.rank}] (source: {src}) {r.chunk.text}")
            sources.append(
                {
                    "rank": r.rank,
                    "source": src,
                    "text": r.chunk.text,
                    "metadata": dict(r.chunk.metadata),
                    "score": r.score,
                }
            )
        context = "\n\n".join(context_parts)

        generator = llm or self.llm
        if generator is not None:
            try:
                answer_text = generator(query, context)
                confidence = 0.8  # optimistic; groundedness() can verify offline
            except Exception:
                answer_text, confidence = extractive_answer(query, results)
        else:
            answer_text, confidence = extractive_answer(query, results)

        return {
            "query": query,
            "answer": answer_text,
            "confidence": confidence,
            "sources": sources,
            "context": context,
        }

    # -- persistence ------------------------------------------------------

    def save(self, path: str) -> None:
        payload = {
            "version": 1,
            "embedder": self.embedder.name,
            "chunks": [
                {
                    "text": c.text,
                    "metadata": c.metadata,
                    "chunk_id": c.chunk_id,
                    "token_count": c.token_count,
                    "embedding": c.embedding,
                }
                for c in self.store.chunks
            ],
        }
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False, indent=2)

    @classmethod
    def load(cls, path: str, embedder: Optional[BaseEmbedder] = None) -> "MetadataRAG":
        with open(path, "r", encoding="utf-8") as fh:
            payload = json.load(fh)
        rag = cls(embedder=embedder or make_embedder(payload.get("embedder", "hash")))
        chunks: List[Chunk] = []
        for item in payload.get("chunks", []):
            chunk = Chunk(
                text=item["text"],
                metadata=item.get("metadata", {}),
                chunk_id=item.get("chunk_id", ""),
                token_count=item.get("token_count", 0),
                embedding=item.get("embedding"),
            )
            if chunk.embedding is None:
                chunk.embedding = rag.embedder.embed(chunk.text)
            chunks.append(chunk)
        rag.store.add_chunks(chunks)
        return rag


# --------------------------------------------------------------------------
# Evaluation helpers
# --------------------------------------------------------------------------


def groundedness(answer: str, context: str) -> float:
    """Fraction of answer tokens that appear in the retrieved context (0-1)."""
    answer_tokens = set(tokenize(answer))
    if not answer_tokens:
        return 0.0
    context_tokens = set(tokenize(context))
    return round(len(answer_tokens & context_tokens) / len(answer_tokens), 4)


def evaluate_retrieval(
    rag: MetadataRAG,
    queries: Sequence[str],
    relevant: Mapping[str, Sequence[int]],
    filter_spec: Optional[Mapping[str, Any]] = None,
    k: int = 5,
) -> Dict[str, float]:
    """Retrieval quality over labelled queries.

    ``relevant`` maps a query string to a list of relevant chunk indices
    (positions in ``rag.store.chunks``). Returns hit rate, MRR, and
    precision@k.
    """
    id_to_index = {c.chunk_id: i for i, c in enumerate(rag.store.chunks)}
    hits_total = 0.0
    mrr_total = 0.0
    precision_total = 0.0
    n = len(queries)
    for query in queries:
        rel = set(relevant.get(query, ()))
        if not rel:
            continue
        results = rag.search(query, filter_spec=filter_spec, k=k)
        retrieved = [
            id_to_index[r.chunk.chunk_id]
            for r in results
            if r.chunk.chunk_id in id_to_index
        ]
        hit_positions = [pos for pos, idx in enumerate(retrieved) if idx in rel]
        if hit_positions:
            hits_total += 1.0
            mrr_total += 1.0 / (hit_positions[0] + 1)
        if retrieved:
            precision_total += len([idx for idx in retrieved if idx in rel]) / k
    return {
        "hit_rate": round(hits_total / n, 4) if n else 0.0,
        "mrr": round(mrr_total / n, 4) if n else 0.0,
        "precision_at_k": round(precision_total / n, 4) if n else 0.0,
    }


